    35  /*static*/ void FileBase::chmod(const char *name, int mode) {
    36      assert(name != nullptr && name[0] != 0);
    37  #if HAVE_CHMOD
    38      if (::chmod(name, mode) != 0)
    39          throwIOException(name, errno);
    40  #else
    41      UNUSED(name);
    42      UNUSED(mode);
    43      // no error
    44  #endif
    45  }
    46
    47  /*static*/ void FileBase::rename(const char *old_, const char *new_) {
    48  #if (ACC_OS_DOS32) && defined(__DJGPP__)
    49      if (::_rename(old_, new_) != 0)
    50  #else
    51      if (::rename(old_, new_) != 0)
    52  #endif
    53          throwIOException("rename error", errno);
    54  }
    55
    56  /*static*/ bool FileBase::unlink_noexcept(const char *name) noexcept {
    57      assert_noexcept(name != nullptr && name[0] != 0);
    58      bool success = ::unlink(name) == 0;
    59  #if HAVE_CHMOD
    60      if (!success)
    61          success = (::chmod(name, 0666) == 0 && ::unlink(name) == 0);
    62  #endif
    63      return success;
    64  }
    65
    66  /*static*/ void FileBase::unlink(const char *name) {
    67      if (!unlink_noexcept(name))
    68          throwIOException(name, errno);
    69  }
