    75  FileBase::~FileBase() may_throw {
    76  #if 0 && defined(__GNUC__) // debug
    77      if (isOpen())
    78          fprintf(stderr, "%s: %s\n", _name, __PRETTY_FUNCTION__);
    79  #endif
    80      if (std::uncaught_exceptions() == 0)
    81          closex(); // may_throw
    82      else
    83          close_noexcept(); // currently in exception unwinding, use noexcept variant
    84  }
