   109  bool FileBase::close_noexcept() noexcept {
   110      bool ok = true;
   111      if (isOpen() && _fd != STDIN_FILENO && _fd != STDOUT_FILENO && _fd != STDERR_FILENO)
   112          if (::close(_fd) == -1)
   113              ok = false;
   114      _fd = -1;
   115      _flags = 0;
   116      _mode = 0;
   117      _name = nullptr;
   118      _offset = 0;
   119      _length = 0;
   120      return ok;
   121  }
   122
   123  void FileBase::closex() may_throw {
   124      if (!close_noexcept())
   125          throwIOException("close failed", errno);
   126  }
