   151  upx_off_t FileBase::tell() const {
   152      if (!isOpen())
   153          throwIOException("bad tell");
   154      upx_off_t l = ::lseek(_fd, 0, SEEK_CUR);
   155      if (l < 0)
   156          throwIOException("tell error", errno);
   157      return l - _offset;
   158  }
