   190  int InputFile::read(SPAN_P(void) buf, upx_int64_t blen) {
   191      if (!isOpen() || blen < 0)
   192          throwIOException("bad read");
   193      int len = (int) mem_size(1, blen); // sanity check
   194      errno = 0;
   195      long l = acc_safe_hread(_fd, raw_bytes(buf, len), len);
   196      if (errno)
   197          throwIOException("read error", errno);
   198      return (int) l;
   199  }
