   217  int InputFile::dupFd() may_throw {
   218      if (!isOpen())
   219          throwIOException("bad dup");
   220  #if defined(HAVE_DUP) && (HAVE_DUP + 0 == 0)
   221      errno = ENOSYS;
   222      int r = -1;
   223  #else
   224      int r = ::dup(getFd());
   225  #endif
   226      if (r < 0)
   227          throwIOException("dup", errno);
   228      return r;
   229  }
